"""WebSocket 服务端 — 前端实时通信（流式对话 + 状态推送）。"""
import asyncio
import json
import logging
import time
import uuid

from fastapi import APIRouter, WebSocket, WebSocketDisconnect

logger = logging.getLogger('agent.ws_handler')
router = APIRouter(tags=['websocket'])


class ConnectionManager:
    """管理所有前端 WebSocket 连接。"""

    def __init__(self):
        self.active: dict[str, WebSocket] = {}

    async def connect(self, ws: WebSocket, client_id: str):
        await ws.accept()
        self.active[client_id] = ws
        logger.info('前端 WS 连接已建立: %s (总计 %d)', client_id, len(self.active))

    def disconnect(self, client_id: str):
        self.active.pop(client_id, None)
        logger.info('前端 WS 连接已断开: %s (总计 %d)', client_id, len(self.active))

    async def send_json(self, client_id: str, data: dict):
        ws = self.active.get(client_id)
        if ws:
            try:
                await ws.send_json(data)
            except Exception:
                self.disconnect(client_id)

    async def broadcast(self, data: dict):
        for cid, ws in list(self.active.items()):
            try:
                await ws.send_json(data)
            except Exception:
                self.disconnect(cid)


manager = ConnectionManager()


@router.websocket('/ws')
async def websocket_endpoint(ws: WebSocket):
    """前端 WebSocket 端点。

    消息协议：
    入站（前端 → 服务器）：
      {"type": "chat", "message": "...", "session_id": "..."}
      {"type": "command", "command": "/status"}
      {"type": "ping"}

    出站（服务器 → 前端）：
      {"type": "session", "session_id": "..."}
      {"type": "delta", "content": "..."}
      {"type": "done", "elapsed_ms": 123}
      {"type": "pong"}
      {"type": "error", "message": "..."}
    """
    client_id = str(uuid.uuid4())[:8]
    await manager.connect(ws, client_id)

    try:
        while True:
            data = await ws.receive_text()
            try:
                msg = json.loads(data)
            except json.JSONDecodeError:
                await ws.send_json({'type': 'error', 'message': 'JSON 解析失败'})
                continue

            msg_type = msg.get('type', '')

            if msg_type == 'ping':
                await ws.send_json({'type': 'pong', 'timestamp': time.time()})

            elif msg_type == 'chat':
                await _handle_chat(ws, msg, client_id)

            elif msg_type == 'command':
                await _handle_command(ws, msg)

            else:
                await ws.send_json({
                    'type': 'error',
                    'message': f'未知消息类型: {msg_type}'
                })

    except WebSocketDisconnect:
        manager.disconnect(client_id)
    except Exception as e:
        logger.exception('WS 处理异常: %s', e)
        manager.disconnect(client_id)


async def _handle_chat(ws: WebSocket, msg: dict, client_id: str):
    """处理聊天消息 — 流式回复。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        await ws.send_json({'type': 'error', 'message': 'Agent 未初始化'})
        return

    session_id = msg.get('session_id') or str(uuid.uuid4())[:8]
    message = msg.get('message', '')
    sender = msg.get('sender')

    await ws.send_json({'type': 'session', 'session_id': session_id})

    t0 = time.monotonic()
    loop = asyncio.get_event_loop()

    def _collect():
        chunks = []
        for chunk in app.process_message_stream(message, sender=sender):
            chunks.append(chunk)
        return chunks

    try:
        chunks = await loop.run_in_executor(None, _collect)
        for chunk in chunks:
            await ws.send_json({'type': 'delta', 'content': chunk})

        elapsed = (time.monotonic() - t0) * 1000
        await ws.send_json({'type': 'done', 'elapsed_ms': round(elapsed, 1)})
    except Exception as e:
        logger.exception('Chat 处理异常: %s', e)
        await ws.send_json({'type': 'error', 'message': str(e)})


async def _handle_command(ws: WebSocket, msg: dict):
    """处理指令消息。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        await ws.send_json({'type': 'error', 'message': 'Agent 未初始化'})
        return

    cmd = msg.get('command', '')
    if not cmd.startswith('/'):
        cmd = '/' + cmd

    try:
        result = app.commands.execute(cmd, app=app, args_str=msg.get('args', ''))
        output = result.get('output') if isinstance(result, dict) else str(result)
        await ws.send_json({'type': 'command_result', 'command': cmd, 'output': output})
    except Exception as e:
        await ws.send_json({'type': 'error', 'message': str(e)})
